-- Series batches: complete Golgo 13 (VIZ paperback, vols 8-13 of 13) and
-- Astro Boy (Dark Horse paperback, vols 16-23 of 23) for staff review.
--
-- Astro Boy ISBNs come from Dark Horse's own product pages (vol 21's page
-- shows no ISBN, so Anime News Network's release record is the reference).
-- Golgo 13 ISBNs come from Simon & Schuster and other retailer listings.
-- Nothing enters the catalogue until a person approves it on Catalogue
-- review ("Select a series"). Dates and covers are left empty.
--
-- Additive only. To undo before review:
--   delete from catalogue_import_queue
--   where raw_payload ? 'series_batch' and status = 'pending_review'
--     and candidate_series in ('Golgo 13', 'Astro Boy');

begin;

insert into public.catalogue_import_queue
